  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 Timelines, Calendars and Cause and Effect$j$, $j${"readings": [{"title": "Ecclesiastes 1 (King James Version)", "url": "/portal/bible/Ecclesiastes/1"}], "body": "History is the record and study of the past. Ecclesiastes 1:9 says, The thing that hath been, it is that which shall be; and that which is done is that which shall be done: and there is no new thing under the sun. A student who knows the past can understand the present with more wisdom.\n\nA timeline places events in order. It helps us see what came first, what came next and how events connect. Historians use several tools to measure time:\nA century is 100 years and a millennium is 1,000 years.\nBC means before Christ and AD means Anno Domini, in the year of our Lord. Many scholars also write BCE and CE for the same dates. The year numbers are the same.\nDifferent peoples used different calendars, such as the Hebrew, Islamic, Chinese and Roman calendars.\n\nCause and effect is the heart of history. A cause is why something happened. An effect is what happened as a result. Most events have both long term causes and an immediate trigger. For example, the long term causes of the French Revolution include debt and unfair taxes, and the immediate trigger was the crisis over bread and the Estates General.\n\nYour task: (1) Place these events on a timeline: fall of Western Rome in 476, Council of Nicaea in 325, Columbus's first voyage in 1492. (2) Tell what century the year 1453 belongs to. (3) Give one cause and one effect of the printing press.\n\nFlorida standards: SS.912.W.1.1, SS.912.W.1.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.1.1, SS.912.W.1.2", "script": "Welcome to World History 1. I am Dr. Alex L. Jenkins Sr., and I am honored to walk through the story of the nations with you. Listen, history is not a pile of dead dates. It is the record of how people lived, worshipped, fought, built and believed. Ecclesiastes one and nine says, The thing that hath been, it is that which shall be; and that which is done is that which shall be done: and there is no new thing under the sun. When you know the past, you gain wisdom for the present.\n\nNow watch this. A timeline puts events in order so you can see what came first and how things connect. A century is one hundred years. A millennium is one thousand years. We write BC for before Christ and AD for Anno Domini, in the year of our Lord. Scholars also use BCE and CE, and the numbers are the same. Peoples around the world kept different calendars, the Hebrew, the Islamic, the Chinese and the Roman, and a good historian learns to read them.\n\nLook at this. Cause and effect is the heart of history. A cause is why something happened. An effect is what followed. Most big events have long term causes and a trigger that lights the fuse. The French Revolution had long term causes in debt and unfair taxes, and a trigger in the bread crisis and the meeting of the Estates General.\n\nYour task today. Place three events on a timeline, tell what century 1453 belongs to, and give one cause and one effect of the printing press. Then take the four question check.\n\nRemember, the Lord rules over time itself. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 Timelines, Calendars and Cause and Effect$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 Primary and Secondary Sources$j$, $j${"readings": [{"title": "Luke 1 (King James Version)", "url": "/portal/bible/Luke/1"}], "body": "Historians learn about the past from sources. A primary source comes from the time being studied, such as a letter, a law, a treaty, a diary, a photograph, a coin or a speech. A secondary source is written later by someone who studied the evidence, such as a textbook, a biography or an encyclopedia article.\n\nWhen you study a source, ask these questions:\nWho made it, and when?\nWhy was it made, and for whom?\nWhat does it say, and what does it leave out?\nIs the author trying to persuade, record or entertain?\nCan I compare it with another source?\n\nA source may be useful even when it has a bias. A king's royal decree shows what the king wanted people to believe. Historians do not trust one source alone. They corroborate, which means they check one source against others.\n\nThe Bible is also read as an ancient source. Luke 1:3 and 4 shows a careful writer who had perfect understanding of all things from the very first and wrote in order, that the reader might know the certainty of those things.\n\nYour task: (1) Sort these into primary or secondary: the Magna Carta, a modern biography of Charlemagne, a diary of a soldier, a history textbook. (2) Explain what bias means. (3) Tell why using two sources is better than one.\n\nFlorida standards: SS.912.W.1.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.1.3", "script": "Welcome back. Listen, a historian is like a good detective, and the clues are called sources. A primary source comes from the time being studied. It could be a letter, a law, a treaty, a diary, a coin or a speech. A secondary source is written later by someone who studied the evidence, like a textbook or a biography.\n\nNow watch this. When you study a source, ask who made it and when. Ask why it was made and for whom. Ask what it says and what it leaves out. Ask whether the author wants to persuade, to record or to entertain. And ask whether you can compare it with another source.\n\nLook at this. A source can have bias and still be useful. A king's decree tells you what the king wanted people to believe. So we never trust one source alone. We corroborate, which means we check one source against others, the way a careful judge listens to more than one witness.\n\nNotice how Luke was careful. In Luke one, verses three and four, he writes that he had perfect understanding of all things from the very first, and wrote in order, that the reader might know the certainty of those things. That is the heart of honest research.\n\nYour task today. Sort four sources into primary and secondary, explain what bias means, and tell why two sources are better than one. Then take the four question check.\n\nSeek the truth with care. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 Primary and Secondary Sources$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 Historical Inquiry and Competing Interpretations$j$, $j${"readings": [{"title": "Proverbs 18 (King James Version)", "url": "/portal/bible/Proverbs/18"}], "body": "Historians do not simply memorize facts. They ask questions, gather evidence, weigh it and build an argument. This is called historical inquiry. They also use other fields to help them. Archaeologists dig up ancient places and objects. Geographers study how land and climate shaped peoples. Scientists date objects and study old diseases. Economists study trade and money.\n\nHonest historians can reach different conclusions from the same evidence. This is called competing interpretations. For example, scholars debate how much the Black Death changed European society, or what the main reasons were for the Crusades. One scholar may stress religion and another may stress land and trade.\n\nHow do we judge an interpretation? Ask:\nDoes it use strong evidence from reliable sources?\nDoes it explain the facts fairly, or does it ignore facts that disagree?\nDoes it consider the values and times of the people involved?\nIs the writer honest about what is uncertain?\n\nProverbs 18:17 says, He that is first in his own cause seemeth just; but his neighbour cometh and searcheth him. We hear the other side before we judge.\n\nYour task: (1) Name two kinds of scientists or scholars who help historians and what each does. (2) Explain why historians can disagree. (3) Write three questions you would ask before accepting a historian's argument.\n\nFlorida standards: SS.912.W.1.4, SS.912.W.1.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.1.4, SS.912.W.1.5", "script": "Welcome back. Listen, historians do not just memorize facts. They ask questions, gather evidence, weigh it and build an argument. We call that historical inquiry. And they get help. Archaeologists dig up ancient places. Geographers study how land and climate shaped peoples. Scientists date objects and study old diseases. Economists study trade and money.\n\nNow watch this. Honest historians can look at the same evidence and reach different conclusions. We call these competing interpretations. Scholars debate how much the Black Death changed Europe, and what mattered most in causing the Crusades. One stresses religion, another stresses land and trade.\n\nSo how do we judge an argument? Look at this. Does it use strong evidence from reliable sources? Does it explain the facts fairly, or hide the facts that disagree? Does it respect the values and times of the people involved? And is the writer honest about what remains uncertain?\n\nProverbs eighteen and seventeen says, He that is first in his own cause seemeth just; but his neighbour cometh and searcheth him. A wise student hears the other side before judging.\n\nYour task today. Name two kinds of scholars who help historians and what they do. Explain why historians can disagree. And write three questions you would ask before accepting an argument. Take the four question check when you finish.\n\nBe fair, be humble, be careful. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 Historical Inquiry and Competing Interpretations$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 How the Past Shapes Identity: Greece, Rome and Israel$j$, $j${"readings": [{"title": "Acts 17 (King James Version)", "url": "/portal/bible/Acts/17"}], "body": "The past shapes who people believe they are. Families, churches, cities and nations all tell stories about where they came from. Studying history helps us understand our own identity and the identity of others.\n\nThree ancient streams flowed into the civilization of the West:\nGreece gave philosophy, early science, drama and the idea of citizens taking part in government, as in Athens.\nRome gave law, roads, engineering, a large empire and the Latin language, which became the language of learning for centuries.\nIsrael gave the knowledge of one God, the Law and the Prophets, and the moral teaching that every person is accountable to the Creator. Through the Jewish people came the Messiah, Jesus Christ, and the Christian faith spread through the Roman world.\n\nActs 17:26 says, And hath made of one blood all nations of men for to dwell on all the face of the earth, and hath determined the times before appointed, and the bounds of their habitation. Every people has a story, and each person bears the image of God.\n\nLater in this course you will see how these three streams joined with the customs of northern Europe in the Middle Ages.\n\nYour task: (1) Match each gift to Greece, Rome or Israel: philosophy, law and roads, the Ten Commandments. (2) Tell how Latin helped scholars in later centuries. (3) Explain Acts 17:26 in your own words.\n\nFlorida standards: SS.912.W.1.6.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.1.6", "script": "Welcome back. Listen, the past shapes who people believe they are. Families, churches, cities and nations all tell stories about where they came from. When we study history, we understand ourselves and our neighbors better.\n\nNow watch this. Three ancient streams flowed into the civilization of the West. Greece gave philosophy, early science, drama and the idea of citizens taking part in government, as in Athens. Rome gave law, roads, engineering, a great empire and the Latin language, which became the language of learning for a thousand years. And Israel gave the knowledge of one God, the Law and the Prophets, and the truth that every person answers to the Creator. Through the Jewish people came the Messiah, Jesus Christ, and the gospel spread along Roman roads.\n\nLook at this. Acts seventeen and twenty six says, And hath made of one blood all nations of men for to dwell on all the face of the earth, and hath determined the times before appointed, and the bounds of their habitation. Every people has a story, and every person bears the image of God.\n\nLater in this course you will see how these three streams joined with the customs of northern Europe to form medieval civilization.\n\nYour task today. Match three gifts to Greece, Rome or Israel. Tell how Latin helped scholars. And explain Acts seventeen and twenty six in your own words. Then take the four question check.\n\nGod is the Lord of history. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 How the Past Shapes Identity: Greece, Rome and Israel$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: Source Analysis and Timeline$j$, $j${"prompt": "Show that you can think like a historian. Write complete sentences and label each part. Ecclesiastes 1:9 says, The thing that hath been, it is that which shall be; and that which is done is that which shall be done: and there is no new thing under the sun.\n\nPart 1: Make a timeline with at least six events from this unit or from your own reading, placing each in the correct century and marking BC or AD.\nPart 2: Choose one primary source (for example, a famous law, letter or speech) and answer five questions about it: who made it, when, why, for whom and what it leaves out. If you cannot find one, describe a sample source and say it is a sample.\nPart 3: Find a secondary source about the same topic and explain how it differs from the primary source.\nPart 4: Give one example of a long term cause and one immediate trigger for a historical event.\nPart 5: Explain how two historians could disagree about the same event, and write three questions you would use to judge each argument.\nPart 6: Describe one way the past has shaped your own family, church or community identity.", "rubric": "70 points. Timeline: 10 points. Primary source analysis: 14 points. Secondary source comparison: 10 points. Cause and trigger: 10 points. Competing interpretations and judging questions: 14 points. Identity reflection: 8 points. Clear work and complete sentences: 4 points. A score of 49 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: Source Analysis and Timeline$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Why Study the Past?$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains in your own words why a Christian student should study world history, (2) describes the difference between a primary and a secondary source and gives an example of each, (3) tells how hearing more than one side protects us from error, and (4) connects your answer to Daniel 2:21, which says, And he changeth the times and the seasons: he removeth kings, and setteth up kings: he giveth wisdom unto the wise, and knowledge to them that know understanding. Then write a respectful reply of at least 40 words to another student, or answer this question: Why can two honest historians disagree? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Why Study the Past?$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: Timelines, Calendars and Cause and Effect$j$, $j${"questions": [{"q": "A period of 1,000 years is called a:", "options": ["Millennium", "Century", "Decade", "Era of one year"]}, {"q": "The year 1453 belongs to the:", "options": ["Fifteenth century", "Fourteenth century", "Sixteenth century", "Fourteenth millennium"]}, {"q": "A cause in history is:", "options": ["A source written later", "A map of the event", "Why an event happened", "What happened afterward"]}, {"q": "The abbreviation AD stands for:", "options": ["Ancient Dates", "Anno Domini, in the year of our Lord", "After Death", "Another Decade"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Timelines, Calendars and Cause and Effect$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,2,1}'::int[], array[$j$A millennium is 1,000 years.$j$,$j$Years 1401 to 1500 make up the fifteenth century.$j$,$j$A cause explains why something happened.$j$,$j$AD comes from the Latin Anno Domini.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Timelines, Calendars and Cause and Effect$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: Primary and Secondary Sources$j$, $j${"questions": [{"q": "Which is a primary source?", "options": ["An encyclopedia article", "A documentary made last year", "A modern textbook on the war", "A soldier's diary written during the war"]}, {"q": "A secondary source is:", "options": ["A coin from that time", "Written later by someone who studied the evidence", "Made during the event", "Always false"]}, {"q": "To corroborate a source means to:", "options": ["Check it against other sources", "Throw it away", "Copy it exactly", "Change its date"]}, {"q": "Bias in a source means:", "options": ["The source has no author", "The source is always worthless", "The author favors one point of view", "The source is very old"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Primary and Secondary Sources$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,0,2}'::int[], array[$j$A diary comes from the time being studied.$j$,$j$Secondary sources interpret evidence after the fact.$j$,$j$Corroboration compares sources to test their reliability.$j$,$j$Bias is a leaning toward one view, which a historian must notice.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Primary and Secondary Sources$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: Historical Inquiry and Competing Interpretations$j$, $j${"questions": [{"q": "Competing interpretations are:", "options": ["Errors in a timeline", "Different conclusions drawn from the same evidence", "Two copies of one document", "Forgeries"]}, {"q": "Which scholar digs up ancient objects and places?", "options": ["Economist", "Archaeologist", "Legislator", "Diplomat"]}, {"q": "A strong historical argument:", "options": ["Depends on one rumor", "Uses reliable evidence and explains the facts fairly", "Avoids all sources", "Ignores facts that disagree"]}, {"q": "Proverbs 18:17 teaches us to:", "options": ["Hear the other side before judging", "Trust the first speaker only", "Ignore neighbors", "Judge by first impressions"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Historical Inquiry and Competing Interpretations$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,1,0}'::int[], array[$j$Historians may weigh evidence differently and conclude differently.$j$,$j$Archaeologists study the past through physical remains.$j$,$j$Good arguments are built on evidence and fairness.$j$,$j$The neighbour comes and searches him, so we listen to both sides.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Historical Inquiry and Competing Interpretations$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: How the Past Shapes Identity: Greece, Rome and Israel$j$, $j${"questions": [{"q": "Which ancient people gave the West the idea of citizens taking part in government, as in Athens?", "options": ["Egyptians", "Greeks", "Romans only", "Vikings"]}, {"q": "Rome is best known for giving the West:", "options": ["The printing press", "The Ten Commandments", "Gunpowder", "Law, roads and engineering"]}, {"q": "Through Israel came the knowledge of:", "options": ["The Roman Senate", "One God and the Law and the Prophets", "The Silk Road", "Many gods of Olympus"]}, {"q": "Acts 17:26 teaches that:", "options": ["Nations have no purpose", "History is chance", "God made all nations of one blood", "Only one nation matters"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: How the Past Shapes Identity: Greece, Rome and Israel$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,1,2}'::int[], array[$j$Athens developed early citizen participation in government.$j$,$j$Roman law, roads and engineering shaped later civilizations.$j$,$j$The Hebrew Scriptures reveal one God.$j$,$j$God made of one blood all nations of men.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: How the Past Shapes Identity: Greece, Rome and Israel$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: Thinking Like a Historian and the Foundations of the West$j$, $j${"questions": [{"q": "A letter written by a king during a war is a:", "options": ["Timeline", "Theory", "Secondary source", "Primary source"]}, {"q": "A modern biography of Charlemagne is a:", "options": ["Artifact from his time", "Secondary source", "Treaty", "Primary source"]}, {"q": "The year 476 belongs to the:", "options": ["Sixth century", "Fifth century", "First millennium BC", "Fourth century"]}, {"q": "Checking one source against others is called:", "options": ["Imitation", "Exploration", "Prophecy", "Corroboration"]}, {"q": "The immediate trigger of an event is:", "options": ["A source", "The spark that starts it, after long term causes build", "The final effect", "Always a century earlier"]}, {"q": "Which field studies physical remains from the ancient past?", "options": ["Banking", "Theology only", "Archaeology", "Navigation"]}, {"q": "Which was a gift of Rome to the West?", "options": ["Athenian drama", "The Hebrew Scriptures", "The compass", "Roman law and the Latin language"]}, {"q": "Daniel 2:21 teaches that God:", "options": ["Leaves nations to chance", "Changes the times and seasons and sets up kings", "Has no part in history", "Only rules the church"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Thinking Like a Historian and the Foundations of the West$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,1,3,1,2,3,1}'::int[], array[$j$It comes from the time being studied.$j$,$j$A later work written by a person who studied the evidence is secondary.$j$,$j$Years 401 to 500 are the fifth century.$j$,$j$Corroboration tests reliability.$j$,$j$Triggers are the last event that sets things in motion.$j$,$j$Archaeologists excavate and study objects and sites.$j$,$j$Rome gave law, roads and Latin.$j$,$j$He changeth the times and the seasons: he removeth kings, and setteth up kings.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Thinking Like a Historian and the Foundations of the West$j$ on conflict (item_id) do nothing;
